import { spawnSync } from 'node:child_process';
import {
    chmodSync,
    copyFileSync,
    existsSync,
    mkdirSync,
    mkdtempSync,
    readFileSync,
    rmSync,
    writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it, onTestFinished } from 'vitest';

const INFRA = join(process.cwd(), 'infra/aws');

/** 실제 호출처럼 이름만 돌려주는 가짜 aws(값은 절대 싣지 않는다). */
const FAKE_AWS = `#!/usr/bin/env bash
printf '%s' "$FAKE_SSM_JSON"
`;

const GATE = [
    '# generated by fixture',
    '',
    'required REQ_A',
    'required REQ_B',
    'optional OPT_A',
    'optional OPT_B',
    'override OVR_A',
    '',
].join('\n');

interface RunOptions {
    /** 기본은 위 GATE. null이면 게이트 파일을 만들지 않는다. */
    gate?: string | null;
    /** 게이트 경로를 인자로 넘기지 않고 스크립트 옆 기본 위치를 쓴다. */
    useDefaultLocation?: boolean;
}

/**
 * 같은 스크립트를 PATH의 bash와 시스템 `/bin/bash`로 모두 돌린다. macOS의 `/bin/bash`는 3.2라
 * 빈 배열 확장(`set -u`)·`+=` 같은 구버전 동작 차이가 먼저 드러난다.
 */
const BASHES = ['bash', '/bin/bash'].filter(
    bin => bin === 'bash' || existsSync(bin)
);

function runWith(
    bashBin: string,
    ssmNames: readonly string[],
    options: RunOptions = {}
) {
    const { gate = GATE, useDefaultLocation = false } = options;
    const dir = mkdtempSync(join(tmpdir(), 'check-env-'));
    onTestFinished(() => rmSync(dir, { recursive: true, force: true }));
    const infra = join(dir, 'infra');
    const bin = join(dir, 'bin');
    mkdirSync(infra);
    mkdirSync(bin);
    copyFileSync(join(INFRA, 'check-env.sh'), join(infra, 'check-env.sh'));
    copyFileSync(join(INFRA, 'lib.sh'), join(infra, 'lib.sh'));
    writeFileSync(join(infra, '.env'), '');
    writeFileSync(join(bin, 'aws'), FAKE_AWS);
    chmodSync(join(bin, 'aws'), 0o755);
    const gatePath = useDefaultLocation
        ? join(infra, 'env-gate.txt')
        : join(dir, 'gate.txt');
    if (gate !== null) writeFileSync(gatePath, gate);

    const result = spawnSync(
        bashBin,
        [
            join(infra, 'check-env.sh'),
            ...(useDefaultLocation ? [] : [gatePath]),
        ],
        {
            encoding: 'utf8',
            env: {
                NODE_ENV: 'test',
                PATH: `${bin}:${process.env.PATH ?? ''}`,
                FAKE_SSM_JSON: JSON.stringify({
                    Parameters: ssmNames.map(name => ({
                        Name: `/siglens/${name}`,
                    })),
                }),
            },
        }
    );
    return { status: result.status, out: result.stdout + result.stderr };
}

describe.each(BASHES)('check-env.sh (%s)', bashBin => {
    const run = (ssmNames: readonly string[], options: RunOptions = {}) =>
        runWith(bashBin, ssmNames, options);

    it('필수·선택 키가 모두 있으면 성공 줄만 남기고 통과한다', () => {
        const r = run(['REQ_A', 'REQ_B', 'OPT_A', 'OPT_B']);

        expect(r.status).toBe(0);
        expect(r.out).toContain('env completeness OK');
        expect(r.out).not.toContain('WARN');
    });

    it('필수 키가 빠지면 그 키를 나열하고 실패한다', () => {
        const r = run(['REQ_A', 'OPT_A', 'OPT_B']);

        expect(r.status).toBe(1);
        expect(r.out).toContain('1 required env key(s) missing');
        expect(r.out).toContain('- REQ_B');
        expect(r.out).not.toContain('- REQ_A');
        expect(r.out).not.toContain('env completeness OK');
    });

    it('필수와 선택이 함께 빠지면 필수만 이유로 실패한다', () => {
        const r = run(['REQ_A']);

        expect(r.status).toBe(1);
        expect(r.out).toContain('- REQ_B');
        expect(r.out).not.toContain('OPT_A');
    });

    it('선택 키만 빠지면 경고 한 줄을 남기고 통과한다', () => {
        const r = run(['REQ_A', 'REQ_B']);

        expect(r.status).toBe(0);
        expect(r.out).toContain(
            'WARN: 2 optional keys absent from SSM: OPT_A OPT_B'
        );
        expect(r.out.match(/WARN/g)).toHaveLength(1);
        expect(r.out).toContain('env completeness OK');
    });

    it('선택 키 일부만 빠지면 빠진 것만 경고한다', () => {
        const r = run(['REQ_A', 'REQ_B', 'OPT_B']);

        expect(r.status).toBe(0);
        expect(r.out).toContain('WARN: 1 optional keys absent from SSM: OPT_A');
        expect(r.out).not.toContain('OPT_B');
    });

    it('접두사만 같은 키는 있는 것으로 치지 않는다', () => {
        const r = run(['REQ_A', 'REQ_B_EXTRA', 'OPT_A', 'OPT_B']);

        expect(r.status).toBe(1);
        expect(r.out).toContain('- REQ_B');
    });

    it('선택 키가 하나도 없는 목록도 통과한다', () => {
        const r = run(['REQ_A'], { gate: 'required REQ_A\n' });

        expect(r.status).toBe(0);
        expect(r.out).not.toContain('WARN');
    });

    it('override 키는 SSM에 없어도 경고하지 않는다', () => {
        const r = run(['REQ_A', 'REQ_B', 'OPT_A', 'OPT_B']);

        expect(r.status).toBe(0);
        expect(r.out).not.toContain('OVR_A');
    });

    it('override 키만 있는 SSM 누락은 선택 경고에도 들어가지 않는다', () => {
        const r = run(['REQ_A', 'REQ_B']);

        expect(r.out).toContain('optional keys absent from SSM: OPT_A OPT_B');
        expect(r.out).not.toContain('OVR_A');
    });

    it('override 키가 SSM에 없으면 override 경고도 없다', () => {
        const r = run(['REQ_A', 'REQ_B', 'OPT_A', 'OPT_B']);

        expect(r.out).not.toContain('override key(s) set');
    });

    it('override 키가 SSM에 있으면 이름만 한 줄로 알리고 통과한다', () => {
        const gate = `${GATE}override OVR_B\n`;
        const r = run(['REQ_A', 'REQ_B', 'OPT_A', 'OPT_B', 'OVR_A', 'OVR_B'], {
            gate,
        });

        expect(r.status).toBe(0);
        expect(r.out).toContain(
            'WARN: 2 override key(s) set in SSM: OVR_A OVR_B'
        );
        expect(r.out.match(/override key\(s\) set/g)).toHaveLength(1);
        expect(r.out).toContain('env completeness OK');
    });

    it('MIGRATION_GATE는 전용 경고만 내고 override 목록에서는 뺀다', () => {
        const gate = `${GATE}override MIGRATION_GATE\n`;
        const r = run(['REQ_A', 'REQ_B', 'OPT_A', 'OPT_B', 'MIGRATION_GATE'], {
            gate,
        });

        expect(r.status).toBe(0);
        expect(r.out).toContain('WARN: SSM /siglens/MIGRATION_GATE is set');
        expect(r.out).not.toContain('override key(s) set');
    });

    it('필수 키가 빠져 실패할 때 override 경고는 내지 않는다', () => {
        const r = run(['REQ_A', 'OVR_A']);

        expect(r.status).toBe(1);
        expect(r.out).not.toContain('override key(s) set');
    });

    it('마지막 줄에 개행이 없어도 그 줄을 읽는다', () => {
        const r = run(['REQ_A'], { gate: 'required REQ_A\nrequired REQ_B' });

        expect(r.status).toBe(1);
        expect(r.out).toContain('- REQ_B');
    });

    it('개행 없는 마지막 줄이 optional이어도 경고에 든다', () => {
        const r = run(['REQ_A'], { gate: 'required REQ_A\noptional OPT_Z' });

        expect(r.status).toBe(0);
        expect(r.out).toContain('optional keys absent from SSM: OPT_Z');
    });

    it('게이트 파일이 없으면 실패한다', () => {
        const r = run(['REQ_A', 'REQ_B'], { gate: null });

        expect(r.status).toBe(1);
        expect(r.out).toContain('env gate list not found');
    });

    it('필수 키가 0개인 목록이면 실패한다', () => {
        const r = run(['OPT_A'], { gate: '# only comments\noptional OPT_A\n' });

        expect(r.status).toBe(1);
        expect(r.out).toContain('no required keys parsed');
    });

    it('해석할 수 없는 줄이 있으면 실패한다', () => {
        const r = run(['REQ_A'], { gate: 'required REQ_A\nmaybe REQ_B\n' });

        expect(r.status).toBe(1);
        expect(r.out).toContain('unparseable line');
    });

    it('인자가 없으면 스크립트 옆 env-gate.txt를 읽는다', () => {
        const r = run(['REQ_A', 'REQ_B', 'OPT_A', 'OPT_B'], {
            useDefaultLocation: true,
        });

        expect(r.status).toBe(0);
        expect(r.out).toContain('env completeness OK');
    });

    it('커밋된 env-gate.txt를 그대로 파싱한다(가짜 SSM에 전부 있으면 통과)', () => {
        const real = readFileSync(join(INFRA, 'env-gate.txt'), 'utf8');
        const names = real
            .split('\n')
            .map(line => /^(?:required|optional) (\S+)$/.exec(line)?.[1])
            .filter((name): name is string => name !== undefined);

        const r = run(names, { gate: real });

        expect(names.length).toBeGreaterThan(0);
        expect(r.status).toBe(0);
        expect(r.out).toContain('env completeness OK');
        expect(r.out).not.toContain('optional keys absent');
    });

    it('커밋된 env-gate.txt에서 SSM이 비어 있으면 필수 키가 전부 누락으로 나온다', () => {
        const real = readFileSync(join(INFRA, 'env-gate.txt'), 'utf8');
        const required = real
            .split('\n')
            .filter(line => line.startsWith('required '));

        const r = run([], { gate: real });

        expect(r.status).toBe(1);
        expect(r.out).toContain(
            `${required.length} required env key(s) missing`
        );
    });
});
